        .VIEWS(MIDI_VIEWS),
        .RETIREMENTS(MIDI_RETIREMENTS),
        .MAINTENANCE(MIDI_MAINTENANCE)
    ) midi (
        .clk(clk),
        .reset(reset),
        .arena_base(midi_arena_base),
        .quantum_frames(phase==IDLE ? run_quantum : saved_run_quantum),
        .arena_bytes(midi_arena_bytes),
        .prepare_valid(accepted),
        .prepare_ready(prepare_ready),
        .prepare_done(prepare_done),
        .prepare_error(prepare_error),
        .event_address(midi_event_address),
        .event_count(midi_event_count),
        .finish_valid(phase==FINISH && !finish_accepted),
        .finish_ready(finish_ready),
        .finish_done(finish_done),
        .finish_error(finish_error),
        .idle(midi_idle),
        .control_enable(phase==IDLE && !run_valid),
        .fault_request(audio_error!=0),
        .publication_valid(midi_publication_valid),
        .publication_commit(midi_publication_commit),
        .job_valid(midi_job_valid),
        .job_ready(midi_job_ready),
        .job_data(midi_job_data),
        .job_done(midi_job_done),
        .job_error(midi_job_error),
        .command_valid(midi_command_valid),
        .command_ready(midi_command_ready),
        .command_op(midi_command_op),
        .command_arg0(midi_command_arg0),
        .command_arg1(midi_command_arg1),
        .command_arg2(midi_command_arg2),
        .command_arg3(midi_command_arg3),
        .command_arg4(midi_command_arg4),
        .response_valid(midi_response_valid),
        .response_ready(midi_response_ready),
        .response_error(midi_response_error),
        .response_handle(midi_response_handle),
        .response_frame(midi_response_frame),
        .response_count(midi_response_count),
        .response_packet(midi_response_packet),
        .response_length(midi_response_length),
        .packet_valid(midi_packet_valid),
        .packet_ready(midi_packet_ready),
        .packet_refused(midi_packet_refused),
        .packet_data(midi_packet_data),
        .packet_length(midi_packet_length),
        .packet_destination(midi_packet_destination),
        .packet_offset(midi_packet_offset),
        .memory_valid(midi_memory_valid),
        .memory_ready(midi_memory_ready),
        .memory_write(midi_memory_write),
        .memory_address(midi_memory_address),
        .memory_write_data(midi_memory_write_data),
        .memory_response_valid(midi_memory_response_valid),
        .memory_response_ready(midi_memory_response_ready),
        .memory_response_error(midi_memory_response_error),
        .memory_read_data(midi_memory_read_data)
    );
